import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import axios from 'axios';

const Dashboard = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [problems, setProblems] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchProblems();
  }, []);

  const fetchProblems = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:5000/api/problems', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProblems(response.data.problems || []);
    } catch (error) {
      console.error('Error fetching problems:', error);
    } finally {
      setLoading(false);
    }
  };

  const totalProblems = problems.length;
  const solved = user?.stats?.problemsSolved || 0;
  const attempts = user?.stats?.totalAttempts || 0;
  const successRate = attempts > 0 ? Math.round((solved / attempts) * 100) : 0;

  return (
    <div style={styles.container}>
      {/* STATS ROW */}
      <div style={styles.statsRow}>
        <div style={styles.statItem}>
          <span style={styles.statNumber}>{totalProblems}</span>
          <span style={styles.statLabel}>Total Problems</span>
        </div>
        <div style={styles.statItem}>
          <span style={styles.statNumber}>{solved}</span>
          <span style={styles.statLabel}>Solved</span>
        </div>
        <div style={styles.statItem}>
          <span style={styles.statNumber}>{attempts}</span>
          <span style={styles.statLabel}>Attempts</span>
        </div>
        <div style={styles.statItem}>
          <span style={styles.statNumber}>{successRate}%</span>
          <span style={styles.statLabel}>Success Rate</span>
        </div>
      </div>

      {/* ASSIGNMENTS - CLEAN VERSION */}
      <div style={styles.assignmentsSection}>
        <h2 style={styles.sectionTitle}>📋 Problems</h2>

        <div style={styles.problemList}>
          {loading ? (
            <div style={styles.loadingText}>Loading...</div>
          ) : problems.length === 0 ? (
            <div style={styles.emptyState}>No problems available</div>
          ) : (
            problems.map((problem, index) => (
              <div
                key={problem._id}
                style={styles.problemRow}
                onClick={() => navigate(`/problems/${problem._id}`)}
              >
                <div style={styles.rowContent}>
                  <div style={styles.leftSection}>
                    <span style={styles.problemId}>#{index + 1}</span>
                    <span style={styles.problemTitle}>{problem.title}</span>
                  </div>
                  <div style={styles.rightSection}>
                    <span style={{
                      ...styles.difficultyBadge,
                      background:
                        problem.difficulty === 'Easy'
                          ? '#28a745'
                          : problem.difficulty === 'Medium'
                          ? '#ffc107'
                          : '#dc3545',
                      color: problem.difficulty === 'Medium' ? '#333' : 'white',
                    }}>
                      {problem.difficulty || 'Easy'}
                    </span>
                    <button style={styles.solveBtn}>Solve →</button>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

const styles = {
  container: {
    minHeight: '100vh',
    background: '#f0f2f5',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
  },

  statsRow: {
    display: 'flex',
    gap: '40px',
    padding: '14px 24px',
    background: 'white',
    borderBottom: '1px solid #e8e8e8',
    flexWrap: 'wrap',
  },
  statItem: {
    display: 'flex',
    alignItems: 'baseline',
    gap: '8px',
  },
  statNumber: {
    fontSize: '22px',
    fontWeight: 700,
    color: '#1a1a2e',
  },
  statLabel: {
    fontSize: '13px',
    color: '#888',
  },

  assignmentsSection: {
    padding: '20px 24px 24px 24px',
  },
  sectionTitle: {
    fontSize: '18px',
    fontWeight: 600,
    color: '#1a1a2e',
    marginBottom: '16px',
  },

  problemList: {
    display: 'flex',
    flexDirection: 'column',
    gap: '10px',
  },

  problemRow: {
    background: 'white',
    borderRadius: '10px',
    padding: '14px 20px',
    border: '1px solid #e8e8e8',
    cursor: 'pointer',
    transition: 'all 0.2s',
    display: 'flex',
    alignItems: 'center',
  },
  rowContent: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    width: '100%',
  },
  leftSection: {
    display: 'flex',
    alignItems: 'center',
    gap: '16px',
  },
  problemId: {
    fontSize: '13px',
    fontWeight: 600,
    color: '#aaa',
    minWidth: '40px',
  },
  problemTitle: {
    fontSize: '16px',
    fontWeight: 500,
    color: '#1a1a2e',
  },
  rightSection: {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
  },
  difficultyBadge: {
    padding: '3px 14px',
    borderRadius: '12px',
    fontSize: '11px',
    fontWeight: 600,
    color: 'white',
  },
  solveBtn: {
    padding: '6px 20px',
    background: '#FF8C00',
    color: 'white',
    border: 'none',
    borderRadius: '6px',
    fontSize: '13px',
    fontWeight: 600,
    cursor: 'pointer',
  },
  loadingText: {
    textAlign: 'center',
    padding: '40px',
    color: '#666',
  },
  emptyState: {
    textAlign: 'center',
    padding: '40px',
    color: '#666',
  },
};

export default Dashboard;
